uired placeholder="دلیل خروج"><button class="btn btn-sm btn-outline-danger">خروج</button></form>@endif</td></tr>@empty<tr><td colspan="10">فاکتوری در سند نیست.</td></tr>@endforelse</tbody></table></div>{{ $items->links() }}</div>
<div class="doc-card mt-3"><h2 class="h5">اصلاحات دوره</h2><div class="table-responsive"><table class="doc-table"><thead><tr><th>نوع</th><th>فاکتور</th><th>دوره منبع</th><th>پایه</th><th>کمپین</th><th>جمع</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>@forelse($corrections as $correction)<tr><td>{{ $correction->description }}</td><td>{{ $correction->source_invoice_number ?: '—' }}</td><td>{{ $correction->source_period_label ?: '—' }}</td><td>{{ \App\Support\Currency::formatToman($correction->base_amount) }}</td><td>{{ \App\Support\Currency::formatToman($correction->campaign_amount) }}</td><td>{{ \App\Support\Currency::formatToman($correction->total_amount) }}</td><td>{{ ['pending'=>'در انتظار','approved'=>'تأییدشده','rejected'=>'ردشده'][$correction->status] }}</td><td>@if($permissions['review'] && $correction->status !== 'approved')<form class="d-inline" method="post" action="{{ route('commercial.commissions.documents.corrections.approve',[$document,$correction]) }}">@csrf<button class="btn btn-sm btn-success">تأیید</button></form>@endif @if($permissions['review'] && $correction->status !== 'rejected')<form class="d-inline" method="post" action="{{ route('commercial.commissions.documents.corrections.reject',[$document,$correction]) }}">@csrf<input name="reason" required placeholder="دلیل رد"><button class="btn btn-sm btn-danger">رد</button></form>@endif</td></tr>@empty<tr><td colspan="8">اصلاحی برای این دوره وجود ندارد.</td></tr>@endforelse</tbody></table></div>{{ $corrections->links() }}</div>
