@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const input=document.getElementById('invoiceSearch'),box=document.getElementById('invoiceResults'),root=input?.closest('[data-search-url]');let timer;input?.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(async()=>{const u=new URL(root.dataset.searchUrl);u.searchParams.set('q',input.value);const j=await(await fetch(u,{headers:{Accept:'application/json'}})).json();box.innerHTML=j.items.map(x=>`<div class="border rounded p-2 mb-2"><b>${x.number}</b> — ${x.date??''} — ${x.customer??''} — ${x.seller??''}<br>پورسانت: ${x.commission_display??'—'} | دوره: ${x.source_period??'—'}<br>${x.available?`<form method="post" action="{{ route('commercial.commissions.documents.invoices.store',$document) }}">@csrf<input type="hidden" name="invoice_id" value="${x.id}">${x.outside_period?'<input class="form-control my-1" name="outside_period_reason" required placeholder="دلیل افزودن خارج دوره">':''}<button class="btn btn-sm btn-primary">افزودن</button></form>`:`<span class="text-danger">${x.reason}</span>`}</div>`).join('')||'نتیجه‌ای نیست.'},250)});document.querySelectorAll('.breakdown').forEach(b=>b.addEventListener('click',async()=>{const j=await(await fetch(b.dataset.url,{headers:{Accept:'application/json'}})).json();alert(j.items.map(x=>`${x.product} / ${x.variant??''}: ${x.net_sale_display} × ${x.effective_rate}% = ${x.commission_display}`).join('\n')||'ریز فعالی موجود نیست.')}))});</script>@endpush
